"""Independent correctness checks; the supplied tests.py is left unchanged."""

from itertools import product
from random import Random
import unittest

from src.component import count_valid_colorings

MODULUS = 998244353


def reference_count(n: int, m: int) -> int:
    """Fix the first color and track whether the last color matches it."""
    same, different = 1, 0
    for _ in range(n - 1):
        same, different = different, (
            same * (m - 1) + different * (m - 2)
        ) % MODULUS
    return m * different % MODULUS


class CountValidColoringsTests(unittest.TestCase):
    def test_examples(self):
        for n, m, expected in (
            (3, 3, 6),
            (4, 2, 2),
            (987654, 456789, 778634319),
        ):
            with self.subTest(n=n, m=m):
                self.assertEqual(count_valid_colorings(n, m), expected)

    def test_exhaustive_small_circles(self):
        for n in range(2, 9):
            for m in range(2, 5):
                with self.subTest(n=n, m=m):
                    expected = sum(
                        all(colors[i] != colors[(i + 1) % n] for i in range(n))
                        for colors in product(range(m), repeat=n)
                    )
                    self.assertEqual(count_valid_colorings(n, m), expected)

    def test_independent_dynamic_programming(self):
        rng = Random(625446)
        for _ in range(200):
            n, m = rng.randint(2, 2000), rng.randint(2, 10**6)
            with self.subTest(n=n, m=m):
                self.assertEqual(count_valid_colorings(n, m), reference_count(n, m))

    def test_boundaries(self):
        for n in (2, 3, 999999, 1000000):
            with self.subTest(n=n, m=2):
                self.assertEqual(count_valid_colorings(n, 2), 0 if n % 2 else 2)
        for m in (2, 3, 1000000):
            with self.subTest(n=2, m=m):
                self.assertEqual(count_valid_colorings(2, m), m * (m - 1) % MODULUS)
        self.assertEqual(count_valid_colorings(1000000, 1000000), 201471773)

    def test_supplied_expected_value_discrepancy(self):
        # tests.py expects 85696089, one more than the actual count modulo MODULUS.
        expected = reference_count(21180, 536683)
        self.assertEqual(expected, 85696088)
        self.assertEqual(count_valid_colorings(21180, 536683), expected)


if __name__ == "__main__":
    unittest.main()
